import itertools
# regions: sectors UL,UR,S; trapezoids T,L,B,R; side regions OT,OL,OB,OR; corner regions CTL,CTR,CBL,CBR
E=[e.split('-') for e in 'UL-UR UR-S S-UL T-UL T-UR L-UL L-S B-S R-S R-UR T-L L-B B-R R-T OT-T OL-L OB-B OR-R CTL-OT CTL-OL CTR-OT CTR-OR CBL-OL CBL-OB CBR-OB CBR-OR'.split()]
def chi(E):
    V=sorted({v for e in E for v in e}); N={v:{b if a==v else a for a,b in E if v in(a,b)} for v in V}
    def col(k,c,i=0):
        if i==len(V): return True
        for x in range(k):
            if all(c.get(u)!=x for u in N[V[i]]):
                c[V[i]]=x
                if col(k,c,i+1): return True
                del c[V[i]]
        return False
    return min(k for k in range(1,8) if col(k,{}))
print(len(E), chi(E))  # 26 4
print(chi([e for e in E if set(e) not in ({'L','S'},{'R','S'})]))  # 4 even without side-trapezoid/bottom-sector contacts
c=dict(UL=1,UR=2,S=3,T=3,L=2,R=1,B=4,OT=1,OL=1,OR=2,OB=1,CTL=2,CTR=3,CBL=2,CBR=3)
print(all(c[a]!=c[b] for a,b in E))  # True: the solution's colouring is valid
G={'TL':'T L OT OL CTL','TR':'T R OT OR CTR','BL':'B L OB OL CBL','BR':'B R OB OR CBR'}
E3=E+[list(p) for g in G.values() for p in itertools.combinations(g.split(),2)]
print(chi(E3))  # 5 if corner-point contacts were (wrongly) counted
